/// Chill. Cost 0, Exhaust. Channel a Frost orb per enemy. P7-7 retrofit.
pub(crate) fn play_chill(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    let alive = state
        .enemy_uids
        .iter()
        .filter(|uid| {
            state
                .creatures
                .iter()
                .any(|c| c.id == uid.0 && c.current_hp > 0)
        })
        .count();
    for _ in 0..alive {
        orbs::channel_orb(state, Orb::frost());
    }
    EffectResult::Resolved
}

